# Vectorize
# Use word analyzer to capture "Pet Supplies" vs "Animals & Pet Supplies" (share "Pet", "Supplies")
# Avoid "Appliances" vs "Supplies" matching on chars
vectorizer = TfidfVectorizer(analyzer='word', ngram_range=(1, 2), min_df=1)
try:
    X = vectorizer.fit_transform(unique_norms)
except ValueError:
    # Fallback if empty vocab (e.g. all stop words)
    return {t: norm_to_orig[t.lower().strip()].title() for t in terms if isinstance(t, str) and t.strip()}

# Check for zero vectors (terms that didn't generate any tokens)
# This happens if terms are too short or contain only ignored characters
magnitudes = np.array(X.sum(axis=1)).flatten()
valid_mask = magnitudes > 0

# If no valid vectors
if not valid_mask.any():
    return {t: norm_to_orig[t.lower().strip()].title() for t in terms if isinstance(t, str) and t.strip()}

# Filter
X_valid = X[valid_mask]
valid_norms = np.array(unique_norms)[valid_mask]
invalid_norms = np.array(unique_norms)[~valid_mask]

# Calculate n_clusters based on valid terms
n_valid = len(valid_norms)

if n_valid <= n_max:
    # If valid terms are few, don't cluster them, just use identity
    # But we still need to process invalid ones
    norm_to_cluster_name = {norm: norm_to_orig[norm].title() for norm in valid_norms}
else:
    n_clusters = min(n_max, n_valid)
    clustering = AgglomerativeClustering(n_clusters=n_clusters, metric='cosine', linkage='average')
    labels = clustering.fit_predict(X_valid.toarray())

    # Map label -> list of normalized terms
    label_to_norms = {}
    for norm, label in zip(valid_norms, labels):
        if label not in label_to_norms:
            label_to_norms[label] = []
        label_to_norms[label].append(norm)

    # Determine cluster names
    norm_to_cluster_name = {}
    used_names = set()

    for label, group_norms in label_to_norms.items():
        best_norm = sorted(group_norms, key=lambda x: (-norm_counts[x], len(x)))[0]
        best_name = norm_to_orig[best_norm].title()

        if best_name in used_names:
             best_name = f"{best_name} (Other)"
        used_names.add(best_name)

        for norm in group_norms:
            norm_to_cluster_name[norm] = best_name

# Add invalid norms to mapping (mapped to themselves)
for norm in invalid_norms:
    norm_to_cluster_name[norm] = norm_to_orig[norm].title()

# Build final mapping: raw_term -> cluster_name
final_mapping = {}
for t in terms:
    if not isinstance(t, str) or not t.strip(): continue
    norm = t.lower().strip()
    final_mapping[t] = norm_to_cluster_name.get(norm, "Uncategorized")

return final_mapping
